   "type": "verified_law",
   "provision_id": "CPA2019-S2-47-VIII",
   "support_quote": "refusing, after selling goods or rendering services, to take back or withdraw defective goods or to withdraw or discontinue deficient services and to refund the consideration thereof, if paid, within the period stipulated in the bill or cash memo or receipt or in the absence of such stipulation, within a period of thirty days"
  },
  {
   "text": "A consumer complaint can be filed in the District Commission within whose local limits you reside.",
   "type": "verified_law",
   "provision_id": "CPA2019-S34-2",
